Here is a complete, idempotent Google Apps Script that replicates all of the formula logic in memory and outputs the result to a dedicated `Clean` sheet. 

Because it processes everything in arrays rather than writing formulas, it will run in about 1–2 seconds for 420 rows and won't slow down your sheet.

### How to install and run it
1. In your Google Sheet, go to **Extensions > Apps Script**.
2. Delete any code in the editor and paste the script below.
3. Click the **Save** icon (or `Ctrl+S` / `Cmd+S`).
4. Reload your Google Sheet. A new menu called **🧹 Data Cleaning** will appear at the top (Wait a few seconds after the sheet loads for it to pop up).
5. Click **🧹 Data Cleaning > Run Clean Process**. (The first time you run it, Google will ask you to authorize the script).

### The Apps Script

```javascript
/**
 * Adds a custom menu to the Google Sheet on open.
 */
function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('🧹 Data Cleaning')
    .addItem('Run Clean Process', 'cleanSurveyData')
    .addToUi();
}

/**
 * Main function to clean data from 'Raw' and output to 'Clean'.
 * Idempotent: Safe to re-run as it rebuilds the 'Clean' tab from scratch each time.
 */
function cleanSurveyData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const rawSheet = ss.getSheetByName('Raw');
  const mapSheet = ss.getSheetByName('ParkMap');

  if (!rawSheet) {
    SpreadsheetApp.getUi().alert('Error: Could not find a sheet named "Raw". Please rename your source tab to "Raw".');
    return;
  }

  // 1. Load ParkMap into a dictionary for fast lookup
  const parkMap = {};
  if (mapSheet && mapSheet.getLastRow() > 1) {
    const mapData = mapSheet.getRange(2, 1, mapSheet.getLastRow() - 1, 2).getValues();
    mapData.forEach(row => {
      const key = String(row[0]).replace(/[^a-zA-Z]/g, '').toLowerCase();
      const canonical = String(row[1]).trim();
      if (key && canonical) parkMap[key] = canonical;
    });
  }

  // 2. Load Raw Data
  const rawData = rawSheet.getDataRange().getValues();
  if (rawData.length <= 1) {
    SpreadsheetApp.getUi().alert('No data found in Raw sheet.');
    return;
  }
  const rows = rawData.slice(1); // Skip header row

  // 3. First Pass: Normalize fields and build keys for duplicate checking
  const processed = rows.map((row, index) => {
    const rawTs = row[0];
    const rawName = String(row[1] || '');
    const rawEmail = String(row[2] || '');
    const rawJoined = String(row[3] || '');
    const rawPhone = String(row[4] || '');
    const rawPark = String(row[5] || '');

    //G: Normalize Yes/No
    let cleanYN = 'REVIEW';
    const ynTrim = rawJoined.trim().toLowerCase();
    if (/^y(es)?$/.test(ynTrim)) cleanYN = 'Yes';
    else if (/^no?$/.test(ynTrim)) cleanYN = 'No';

    // H: Standardize Phone
    let cleanPhone = 'REVIEW';
    if (rawPhone.trim() !== '') {
      let digits = rawPhone.replace(/\D/g, '');
      if (digits.length === 11 && digits.startsWith('1')) {
        digits = digits.substring(1);
      }
      if (digits.length === 10) {
        // Prepend apostrophe so Sheets forces Plain Text and keeps leading zeros
        cleanPhone = "'" + digits; 
      }
    }

    // I: Standardize Timestamp
    let cleanTs = 'REVIEW';
    let tsMs = null; // Milliseconds since epoch for math comparisons
    if (rawTs instanceof Date && !isNaN(rawTs.getTime())) {
      cleanTs = rawTs;
      tsMs = rawTs.getTime();
    } else if (String(rawTs).trim() !== '') {
      const parsedDate = new Date(String(rawTs).trim());
      if (!isNaN(parsedDate.getTime())) {
        cleanTs = parsedDate;
        tsMs = parsedDate.getTime();
      }
    }

    // J: Consolidate Park Names
    let cleanPark = 'REVIEW';
    const parkKey = rawPark.replace(/[^a-zA-Z]/g, '').toLowerCase();
    if (parkKey !== '' && parkMap[parkKey]) {
      cleanPark = parkMap[parkKey];
    }

    // K & L: Helper Keys
    const emailKey = rawEmail.trim().toLowerCase();
    const nameKey = rawName.trim().replace(/\s+/g, ' ').toLowerCase();

    return {
      rawIndex: index, // Used for tie-breaking identical timestamps
      raw: [rawTs, rawName, rawEmail, rawJoined, rawPhone, rawPark],
      cleanYN,
      cleanPhone,
      cleanTs,
      tsMs,
      cleanPark,
      emailKey,
      nameKey
    };
  });

  // 4. Group by Email and Name for Duplicate Detection
  const emailGroups = {};
  const nameGroups = {};

  processed.forEach(item => {
    if (item.emailKey) {
      if (!emailGroups[item.emailKey]) emailGroups[item.emailKey] = [];
      emailGroups[item.emailKey].push(item);
    }
    if (item.nameKey) {
      if (!nameGroups[item.nameKey]) nameGroups[item.nameKey] = [];
      nameGroups[item.nameKey].push(item);
    }
  });

  // 5. Second Pass: Evaluate Duplicates, Superseded status, and Review Flag
  const TEN_MINS_MS = 10 * 60 * 1000;

  const outputRows = processed.map(item => {
    let dupEmail = '';
    let dupNameTime = '';
    let superseded = '';

    // Check Email Duplicates & Determine Superseded
    if (item.emailKey && emailGroups[item.emailKey].length > 1) {
      dupEmail = 'DUP-email';
      const group = emailGroups[item.emailKey];

      // Find if there is a newer submission for this email
      if (item.tsMs !== null) {
        const hasNewer = group.some(other => {
          if (other.rawIndex === item.rawIndex || other.tsMs === null) return false;
          // Newer if timestamp is greater, OR if timestamps are identical, keep the later row in the sheet
          return (other.tsMs > item.tsMs) || (other.tsMs === item.tsMs && other.rawIndex > item.rawIndex);
        });
        if (hasNewer) superseded = 'SUPERSEDED';
      }
    }

    // Check Name + Time Duplicates (within 10 minutes)
    if (item.nameKey && item.tsMs !== null && nameGroups[item.nameKey].length > 1) {
      const group = nameGroups[item.nameKey];
      const hasNearMatch = group.some(other => {
        if (other.rawIndex === item.rawIndex || other.tsMs === null) return false;
        return Math.abs(other.tsMs - item.tsMs) <= TEN_MINS_MS;
      });
      if (hasNearMatch) dupNameTime = 'DUP-name-time';
    }

    // Overall Manual Review Flag
    let status = 'OK';
    if (
      item.cleanYN === 'REVIEW' ||
      item.cleanPhone === 'REVIEW' ||
      item.cleanTs === 'REVIEW' ||
      item.cleanPark === 'REVIEW' ||
      dupEmail !== '' ||
      dupNameTime !== ''
    ) {
      status = 'REVIEW';
    }

    return [
      ...item.raw,        // A-F: Original Data
      item.cleanYN,       // G
      item.cleanPhone,    // H
      item.cleanTs,       // I
      item.cleanPark,     // J
      item.emailKey,      // K
      item.nameKey,       // L
      dupEmail,           // M
      dupNameTime,        // N
      superseded,         // O
      status              // P
    ];
  });

  // 6. Write to 'Clean' Sheet (Idempotent setup)
  let cleanSheet = ss.getSheetByName('Clean');
  if (!cleanSheet) {
    cleanSheet = ss.insertSheet('Clean');
  } else {
    cleanSheet.clear(); // Clears data and formatting so it's fresh
    if (cleanSheet.getFilter()) cleanSheet.getFilter().remove();
  }

  const headers = [
    'Raw_Timestamp', 'Raw_Name', 'Raw_Email', 'Raw_JoinedBefore', 'Raw_Phone', 'Raw_PreferredPark',
    'Clean_YN', 'Clean_Phone', 'Clean_Timestamp', 'Clean_Park',
    'Key_Email', 'Key_Name', 'Flag_DupEmail', 'Flag_DupNameTime', 'Flag_Superseded', 'Review_Status'
  ];

  const finalData = [headers, ...outputRows];
  const targetRange = cleanSheet.getRange(1, 1, finalData.length, headers.length);
  targetRange.setValues(finalData);

  // 7. Apply Formatting for Readability
  cleanSheet.setFrozenRows(1);
  cleanSheet.getRange(1, 1, 1, headers.length).setFontWeight('bold').setBackground('#f3f3f3');

  // Format Clean_Timestamp column (Column I / Col 9) so dates look right
  if (outputRows.length > 0) {
    cleanSheet.getRange(2, 9, outputRows.length, 1).setNumberFormat('yyyy-mm-dd hh:mm:ss');
  }

  // Add an auto-filter so you can immediately filter by Review_Status
  targetRange.createFilter();

  // Optional: Auto-resize columns (can comment out if you prefer fixed widths)
  cleanSheet.autoResizeColumns(1, headers.length);

  SpreadsheetApp.getUi().alert('Cleaning complete! Check the "Clean" tab.');
}
```

### A few upgrades built into this script vs. the formulas:
1. **Identical-Timestamp Tiebreaker:** In your sample data, Maya Singh submitted twice at `09:12`. A pure formula checking for `>` (greater than) wouldn't mark either as `SUPERSEDED` because the times are equal. This script breaks ties using the row index—so Row 1 gets marked `SUPERSEDED` and Row 2 is kept as the latest.
2. **Auto-Formatting & Filtering:** Every time you run it, it clears the `Clean` tab, writes the fresh data, formats the `Clean_Timestamp` column to `yyyy-mm-dd hh:mm:ss`, freezes the header row, and turns on Filter views automatically.
3. **ParkMap Tolerance:** If you don't have a `ParkMap` tab yet, the script won't crash; it will just mark all parks as `REVIEW` until you create the `ParkMap` tab and re-run it. When you add new parks to `ParkMap`, you don't even need to strip spaces/punctuation in Column A—the script strips them out of `ParkMap` keys automatically on load.

Here is the updated Apps Script with all of those changes integrated. 

Before running, if you want to use the default area code feature, create a tab named `Settings` and put your 3-digit area code (e.g., `206` or `415`) into cell **B1** (you can put a label like "Default Area Code" in A1). If the `Settings` tab doesn't exist or B1 is blank/not 3 digits, 7-digit numbers will safely fall back to `REVIEW`.

