    if (superseded === '' && status === 'OK') keptFinalCount++;
    parkCounts[item.cleanPark] = (parkCounts[item.cleanPark] || 0) + 1;

    return [
      ...item.raw,        // A-F: Original Data
      item.cleanYN,       // G
      item.cleanPhone,    // H
      item.cleanTs,       // I
      item.cleanPark,     // J
      item.emailKey,      // K
      item.nameKey,       // L
      dupEmail,           // M
      dupNameTime,        // N
      superseded,         // O
      status,             // P
      reviewReasons,      // Q
      autoAction          // R
    ];
  });

  // 6. Write to 'Clean' Sheet (Idempotent setup)
  let cleanSheet = ss.getSheetByName('Clean');
  if (!cleanSheet) {
    cleanSheet = ss.insertSheet('Clean');
  } else {
    cleanSheet.clear();
    if (cleanSheet.getFilter()) cleanSheet.getFilter().remove();
  }

  const headers = [
    'Raw_Timestamp', 'Raw_Name', 'Raw_Email', 'Raw_JoinedBefore', 'Raw_Phone', 'Raw_PreferredPark',
    'Clean_YN', 'Clean_Phone', 'Clean_Timestamp', 'Clean_Park',
    'Key_Email', 'Key_Name', 'Flag_DupEmail', 'Flag_DupNameTime', 'Flag_Superseded', 'Review_Status', 'Review_Reasons', 'Auto_Action'
  ];

  const finalData = [headers, ...outputRows];
  const targetRange = cleanSheet.getRange(1, 1, finalData.length, headers.length);
  targetRange.setValues(finalData);

  // Format 'Clean' Sheet
  cleanSheet.setFrozenRows(1);
  cleanSheet.getRange(1, 1, 1, headers.length).setFontWeight('bold').setBackground('#f3f3f3');
  if (outputRows.length > 0) {
    cleanSheet.getRange(2, 9, outputRows.length, 1).setNumberFormat('yyyy-mm-dd hh:mm:ss');
  }
  targetRange.createFilter();
  cleanSheet.autoResizeColumns(1, headers.length);

  // 7. Write to 'CleaningSummary' Sheet (Idempotent setup)
  let summarySheet = ss.getSheetByName('CleaningSummary');
  if (!summarySheet) {
    summarySheet = ss.insertSheet('CleaningSummary');
  } else {
    summarySheet.clear();
  }

  const uniqueEmailsCount = Object.keys(emailGroups).length;
  const summaryRows = [
    ['Metric', 'Count'],
    ['Total raw rows', rows.length],
    ['Rows marked REVIEW', reviewCount],
    ['Rows marked SUPERSEDED', supersededCount],
    ['Rows kept (final)', keptFinalCount],
    ['Unique emails', uniqueEmailsCount],
    ['', ''],
    ['Canonical Park (Clean_Park)', 'Count']
  ];

  // Sort parks alphabetically, keeping 'REVIEW' at the bottom of the list
  const sortedParks = Object.keys(parkCounts).sort((a, b) => {
    if (a === 'REVIEW') return 1;
    if (b === 'REVIEW') return -1;
    return a.localeCompare(b);
  });

  sortedParks.forEach(park => {
    summaryRows.push([park, parkCounts[park]]);
  });

  const summaryRange = summarySheet.getRange(1, 1, summaryRows.length, 2);
  summaryRange.setValues(summaryRows);

  // Format 'CleaningSummary' Sheet
  summarySheet.getRange(1, 1, 1, 2).setFontWeight('bold').setBackground('#f3f3f3');
  summarySheet.getRange(8, 1, 1, 2).setFontWeight('bold').setBackground('#f3f3f3');
  summarySheet.autoResizeColumns(1, 2);

  SpreadsheetApp.getUi().alert('Cleaning complete! Check the "Clean" and "CleaningSummary" tabs.');
}
